{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.ashlesh-t/cognirepo",
  "title": "CogniRepo",
  "description": "FAISS, call graph, AST, BM25 — 34 MCP tools for AI agents. 50-80% token reduction. Offline.",
  "repository": {
    "url": "https://github.com/ashlesh-t/cognirepo",
    "source": "github"
  },
  "version": "2.0.0",
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "cognirepo",
      "version": "2.0.0",
      "runtimeHint": "uvx",
      "transport": {
        "type": "stdio"
      },
      "packageArguments": [
        {
          "type": "positional",
          "value": "serve",
          "valueHint": "serve"
        },
        {
          "type": "named",
          "name": "--project-dir",
          "description": "Absolute path to the project root cognirepo should index and serve. Omit to use current working directory.",
          "isRequired": false
        }
      ]
    }
  ]
}
